/* Select the parent element */
.container {
  /* Apply flexbox layout */
  display: flex;
  /* Optional: Define direction (row or column) */
  flex-direction: row;
  /* Optional: Adjust wrapping behavior */
  flex-wrap: wrap;
  /* Optional: Alignment along the main axis */
  justify-content: center;
  /* Optional: Alignment along the cross axis */
  align-items: center;
}

/* Within the flex container */
.item1 {
  order: 1;
}

.item2 {
  order: 2;
}

.item3 {
  order: 3;
}

